WITH recent_orders AS (SELECT * FROM orders WHERE (shipping_fee >= 11 AND channel NOT IN ('mobile', 'web')) OR channel IN ('partner', 'web')), agg AS (SELECT QUARTER(order_date) AS order_quarter, DATE_FORMAT(order_date, 'yyyy-MM') AS order_month, MIN(order_date) AS min_order_date, MAX(order_date) AS latest_order_date FROM recent_orders GROUP BY QUARTER(order_date), DATE_FORMAT(order_date, 'yyyy-MM')) SELECT * FROM agg ORDER BY order_quarter DESC
